import Foundation

struct Question {
    let prompt: String
    let answer: String
}

func score(questions: [Question], answers: [String]) -> Int {
    zip(questions, answers).reduce(into: 0) { count, pair in
        if pair.0.answer.trimmingCharacters(in: .whitespacesAndNewlines).caseInsensitiveCompare(
            pair.1.trimmingCharacters(in: .whitespacesAndNewlines)
        ) == .orderedSame { count += 1 }
    }
}

let questions = [Question(prompt: "2 + 2?", answer: "4"), Question(prompt: "Swift is typed?", answer: "yes")]
print("Score: \(score(questions: questions, answers: ["4", "YES"])) / \(questions.count)")
